/**
 * Practice puzzles. Daily puzzles are chosen on the server only; the app never
 * knows the daily answer. Mirrors generator.py.
 */

import lists from "./answer-lists.json";

export type Rng = () => number;

/**
 * Pre-built answer lists (generated by the Python engine), so phones never
 * spend time computing them. `allAnswers` rebuilds them from the rules, and a
 * test checks the two match.
 */
export function answerList(length: number): readonly string[] {
  const list = (lists as Record<string, string[]>)[String(length)];
  if (!list) throw new RangeError(`no answer list for ${length} tiles`);
  return list;
}

/** Small seedable PRNG; identical output to mulberry32 in generator.py. */
export function mulberry32(seed: number): Rng {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t = (t + Math.imul(t ^ (t >>> 7), t | 61)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const intBelow = (rng: Rng, n: number) => Math.floor(rng() * n);

/** A random good answer of `length` tiles, every answer equally likely. */
export function randomPuzzle(length: number, rng: Rng = Math.random): string {
  const answers = answerList(length);
  return answers[intBelow(rng, answers.length)]!;
}
